<script lang="ts">
 import type{Inspection}from'$lib/server/inspection';
 import TimeChart from './TimeChart.svelte';
 import ValueBars from './ValueBars.svelte';
 import{usd,num,utc,sign}from'$lib/format';
 let {inspection:d}:{inspection:Inspection}=$props();
 const s=$derived(d.subject),c=$derived(d.costs),risk=$derived(d.risk);
 const marks=$derived([{t:s.entryTime,value:s.entryPrice,label:'OPEN'},...(s.exitTime!==null&&s.exitPrice!==null?[{t:s.exitTime,value:s.exitPrice,label:'CLOSE'}]:[])]);
 const pricePrecision=$derived(['EURUSD','GBPUSD','AUDUSD'].includes(s.epic)?5:2);
</script>
<section class="card stack inspection">
 <header class="row heading"><div><h2>{s.side==='long'?'Long':'Short'} · {s.epic}</h2><p class="muted">{utc(s.entryTime)} → {s.exitTime?utc(s.exitTime):'Open'} · {num(s.size,3)} units</p></div><span class="badge">{d.coverage.complete?'Recorded ticks':'Partial tick coverage'}</span></header>
 <TimeChart series={[{name:'Bid',points:d.price.bid},{name:'Ask',points:d.price.ask}]} markers={marks} candles={d.price.candles} gaps={d.coverage.gaps} from={d.window.from} through={d.window.through} unit="Price" precision={pricePrecision} height={280}/>
 <div class="trade-metrics"><div><small>Net P&L</small><strong class={sign(c.net)}>{usd(c.net)}</strong></div><div><small>{risk.fullTrade?'Max price drawdown':'Observed price drawdown'}</small><strong class="down">{risk.maxDrawdown===null?'—':`${risk.fullTrade?'':'≥'}${usd(risk.maxDrawdown)}`}{#if risk.fullTrade&&risk.drawdownFraction!==null}<span> · {num(risk.drawdownFraction*100)}%</span>{/if}</strong></div><div><small>Spread cost</small><strong>{usd(c.spread)}</strong></div><div><small>Funding</small><strong>{usd(c.funding)}</strong></div></div>
 <div class="decisions"><div><small>Why open</small><p>{s.entryReason??'Not recorded'}</p></div><div><small>Why close</small><p>{s.exitTime?(s.exitReason??'Not recorded'):'Still open'}</p></div></div>
 <div class="inspection-grid">
  <div><h3>Executable-price P&L</h3><TimeChart series={[{name:'P&L',points:d.pnl}]} gaps={d.coverage.gaps} from={d.window.from} through={d.window.through} unit="USD · before funding" height={170}/></div>
  <div><h3>{risk.fullTrade?'Price drawdown':'Observed drawdown'}</h3><TimeChart series={[{name:'Drawdown',points:d.drawdown}]} gaps={d.coverage.gaps} from={d.window.from} through={d.window.through} unit="USD · peak to trough" height={170}/></div>
 </div>
 <div class="inspection-grid"><div><h3>Quoted spread</h3><TimeChart series={[{name:'Bid–ask',points:d.spread}]} gaps={d.coverage.gaps} from={d.window.from} through={d.window.through} unit="Points" precision={pricePrecision} height={150}/></div><div><h3>Cost breakdown</h3><ValueBars unit=" USD" items={[...(c.midpoint===null?[]:[{label:'Fill midpoint P&L',value:c.midpoint}]),...(c.spread===null?[]:[{label:'Spread',value:-c.spread}]),...(c.funding===null?[]:[{label:'Funding',value:c.funding}]),...(c.adjustment===null?[]:[{label:'Rounding / protection',value:c.adjustment}]),...(c.net===null?[]:[{label:'Net P&L',value:c.net}])]} />{#if c.timing!==null}<p class="muted small">Decision-to-fill timing cost: {usd(c.timing)} · already included in midpoint P&L.</p>{/if}</div></div>
 <details><summary>Coverage & order timing</summary><div class="table-wrap"><table class="data"><tbody>{#each d.checks as check}<tr><th>{check.label}</th><td>{check.state}</td></tr>{/each}<tr><th>Quotes / fallback candles</th><td>{d.coverage.ticks.toLocaleString()} / {d.coverage.candles}</td></tr>{#each s.timeline as event}<tr><th>{event.label}</th><td>{utc(event.t)}</td></tr>{/each}{#each d.coverage.gaps as gap}<tr><th>Tick gap</th><td>{utc(gap.from)} → {utc(gap.through)}</td></tr>{/each}</tbody></table></div></details>
</section>
<style>.heading{justify-content:space-between}.heading h2{margin:0}.heading p{font-size:12px}.trade-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;border-block:1px solid var(--grid);padding:14px 0}.trade-metrics small,.decisions small{display:block;color:var(--ink-muted);font-size:11px}.trade-metrics strong{font-size:20px;font-variant-numeric:tabular-nums;font-weight:600}.trade-metrics strong span{font-size:12px}.decisions,.inspection-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.decisions{font-size:13px}.inspection h3{margin-bottom:10px}.small{font-size:11px;margin-top:12px}summary{cursor:pointer;font-size:12px;color:var(--ink-2)}details .table-wrap{margin-top:12px}@media(max-width:650px){.inspection-grid{grid-template-columns:1fr}.trade-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.decisions{gap:16px}.trade-metrics strong{font-size:18px}}</style>
